import React, { useEffect, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { api, BACKEND_URL, fmt } from "../lib/api";
import { toast } from "sonner";

export default function Messages() {
  const { user } = useAuth();
  const [params] = useSearchParams();
  const [convs, setConvs] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [other, setOther] = useState(null);
  const [thread, setThread] = useState([]);
  const [text, setText] = useState("");
  const [connectedIds, setConnectedIds] = useState(new Set());
  const [connectionsLoaded, setConnectionsLoaded] = useState(false);
  const wsRef = useRef(null);
  const endRef = useRef(null);
  const activeRef = useRef(activeId);
  useEffect(() => { activeRef.current = activeId; }, [activeId]);

  // Load accepted connections first
  useEffect(() => {
    if (!user?.id) return;
    api.get("/connections").then(r => {
      const accepted = new Set();
      (r.data || []).forEach(c => {
        if (c.status === "accepted") {
          const otherId = c.sender_id === user.id ? c.receiver_id : c.sender_id;
          accepted.add(otherId);
        }
      });
      setConnectedIds(accepted);
      setConnectionsLoaded(true);
    }).catch(() => setConnectionsLoaded(true));
  }, [user?.id]);

  // Once connections are loaded, set activeId from URL param (only if connected)
  useEffect(() => {
    if (!connectionsLoaded) return;
    const toParam = params.get("to");
    if (toParam) {
      if (connectedIds.has(toParam)) {
        setActiveId(toParam);
      } else {
        toast.error("You can only message people you're connected with.");
      }
    }
  }, [connectionsLoaded]);

  const loadConvs = async () => {
    try {
      const { data } = await api.get("/messages/conversations");
      // Only show conversations with accepted connections
      const filtered = data.filter(c => connectedIds.has(c.other_id));
      setConvs(filtered);
      if (!activeId && filtered.length) setActiveId(filtered[0].other_id);
    } catch (_) {}
  };

  useEffect(() => {
    if (connectionsLoaded) loadConvs();
  }, [connectionsLoaded]);

  useEffect(() => {
    if (!activeId) return;
    // Guard: only load thread if connected
    if (!connectedIds.has(activeId)) {
      toast.error("You can only message people you're connected with.");
      setActiveId(null);
      return;
    }
    (async () => {
      const [{ data: t }, { data: u }] = await Promise.all([
        api.get(`/messages/thread/${activeId}`), api.get(`/users/${activeId}`)
      ]);
      setThread(t); setOther(u);
    })();
  }, [activeId]);

  useEffect(() => {
    if (!user?.id) return;
    (async () => {
      try {
        const { data } = await api.post("/auth/ws-token");
        const wsUrl = BACKEND_URL.replace(/^http/, "ws") + `/api/ws/${user.id}?token=${data.token}`;
        const ws = new WebSocket(wsUrl);
        ws.onmessage = (e) => {
          try {
            const p = JSON.parse(e.data);
            if (p.type === "message") {
              const m = p.data;
              const o = activeRef.current;
              if (m.senderId === o || m.receiverId === o) {
                setThread(prev => prev.some(x => x._id === m._id) ? prev : [...prev, m]);
              }
              loadConvs();
            }
          } catch {}
        };
        wsRef.current = ws;
      } catch {}
    })();
    return () => wsRef.current?.close();
  }, [user?.id]);

  useEffect(() => { endRef.current?.scrollIntoView({ behavior: "smooth" }); }, [thread]);

  const send = async (e) => {
    e.preventDefault();
    if (!text.trim() || !activeId) return;
    // Guard: block sending if not connected
    if (!connectedIds.has(activeId)) {
      toast.error("You can only message people you're connected with.");
      return;
    }
    try {
      const { data } = await api.post("/messages", { receiver_id: activeId, content: text.trim() });
      setThread(prev => prev.some(x => x._id === data._id) ? prev : [...prev, data]);
      setText(""); loadConvs();
    } catch (err) { toast.error(fmt(err.response?.data?.detail)); }
  };

  const handleSelectConv = (otherId) => {
    if (!connectedIds.has(otherId)) {
      toast.error("You can only message people you're connected with.");
      return;
    }
    setActiveId(otherId);
  };

  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "2rem" }}>
      <div className="overline">Conversations</div>
      <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0 1.5rem" }}>Messages</h1>

      <div className="card-editorial" style={{ display: "grid", gridTemplateColumns: "300px 1fr", height: 560 }}>

        {/* SIDEBAR */}
        <div style={{ borderRight: "1px solid var(--border)", overflowY: "auto" }}>
          {convs.length === 0 && (
            <div style={{ padding: 20, color: "var(--muted)", fontSize: 14 }}>
              No conversations yet. Connect with someone in the Directory to start messaging.
            </div>
          )}
          {convs.map(c => (
            <button
              key={c.other_id}
              onClick={() => handleSelectConv(c.other_id)}
              style={{
                display: "block", width: "100%", textAlign: "left",
                padding: 16, borderBottom: "1px solid var(--border)",
                background: activeId === c.other_id ? "var(--bone)" : "#fff",
                border: "none", cursor: "pointer",
              }}
            >
              <div style={{ fontWeight: 500, color: "var(--ivy)" }}>{c.other_name}</div>
              <div style={{
                fontSize: 13, color: "var(--muted)",
                overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
              }}>{c.last_message}</div>
            </button>
          ))}
        </div>

        {/* CHAT PANEL */}
        <div style={{ display: "flex", flexDirection: "column" }}>
          {!activeId ? (
            <div style={{ margin: "auto", color: "var(--muted)", textAlign: "center", padding: "2rem" }}>
              <div>Select a conversation</div>
              <div style={{ fontSize: 13, marginTop: 8 }}>
                You can only message people who have accepted your connection request.
              </div>
            </div>
          ) : (
            <>
              <div style={{ padding: 16, borderBottom: "1px solid var(--border)", fontWeight: 500, color: "var(--ivy)" }}>
                {other?.name}
              </div>
              <div style={{ flex: 1, overflowY: "auto", padding: 16 }}>
                {thread.map(m => {
                  const mine = m.senderId === user.id;
                  return (
                    <div key={m._id} style={{ display: "flex", justifyContent: mine ? "flex-end" : "flex-start", marginBottom: 10 }}>
                      <div className={mine ? "bubble-me" : "bubble-them"} style={{ padding: "10px 14px", maxWidth: "70%" }}>
                        <div style={{ fontSize: 14, whiteSpace: "pre-wrap" }}>{m.content}</div>
                      </div>
                    </div>
                  );
                })}
                <div ref={endRef} />
              </div>
              <form onSubmit={send} style={{ padding: 12, borderTop: "1px solid var(--border)", display: "flex", gap: 8 }}>
                <input
                  className="input"
                  placeholder="Write a message…"
                  value={text}
                  onChange={e => setText(e.target.value)}
                />
                <button className="btn-primary" type="submit" disabled={!text.trim()}>Send</button>
              </form>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
